import {echarts} from './assets/echarts.js';
import {sectionLayout} from './layout.js?v=7';

const BOARDS = [
  ['national_team','国家队全景'],['contrarian','逆向投资'],['sentiment','情绪温度计'],['chips','全A筹码结构'],['valuation','市场估值'],['fund_holdings','A股公募持仓'],['capital_flow','A股资金流']
];
const $ = id => document.getElementById(id);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state = {board:'national_team', panel:'', meta:null, data:null, abort:null, sequence:0, charts:[], table:{}, entity:null, version:null, latestVersion:null};
const chartColors = ['#6e9ff5','#55c6bd','#e8b96a','#ef7d7b','#ac91dd','#7fb5d9','#b8cd79','#d78ca9'];
function params(){return new URLSearchParams(location.search)}
function routeState(){const q=params(); state.board=BOARDS.some(b=>b[0]===q.get('desk'))?q.get('desk'):(BOARDS.some(b=>b[0]===q.get('board'))?q.get('board'):'national_team');state.panel=q.get('tab')||'';state.entity=q.get('_detail')||null;state.version=q.get('data_version')||null;state.table={};}
function updateUrl(changes, replace=false){const q=params();for(const [key,value] of Object.entries(changes)){if(value===null||value===undefined||value==='')q.delete(key);else if(Array.isArray(value))q.set(key,value.join(','));else q.set(key,String(value));}const url=`${location.pathname}?${q}`;history[replace?'replaceState':'pushState']({},'',url);}
function cleanupCharts(){state.charts.forEach(c=>c.dispose());state.charts=[]}
function nav(){ $('boards').innerHTML=BOARDS.map(([id,name])=>`<button class="${state.board===id?'active':''}" data-board="${id}">${name}</button>`).join('');$('boards').querySelectorAll('button').forEach(b=>b.onclick=()=>{state.board=b.dataset.board;state.panel='';state.entity=null;state.table={};const q=new URLSearchParams({desk:state.board});if(state.version)q.set('data_version',state.version);history.pushState({},'',`${location.pathname}?${q}`);loadBoard()});$('board-code').textContent=state.board.toUpperCase().replaceAll('_',' ')}
async function request(url,signal){const response=await fetch(new URL(url.slice(1), import.meta.url),{signal,cache:url==='/api/dashboards/health'?'no-store':'default'});if(!response.ok){let detail='';try{const body=await response.json();detail=body.detail||body.message||body.error||''}catch{}throw new Error(detail || `请求失败（${response.status}）`)}return response.json()}
const controlTimers=new Set();
function begin(){for(const timer of controlTimers)clearTimeout(timer);controlTimers.clear();clearTimeout(tableTimer);state.abort?.abort();state.abort=new AbortController();return {signal:state.abort.signal,seq:++state.sequence}}
function showError(e){if(e.name==='AbortError')return;$('status').className='status error';$('status').textContent=`${String(e.message).replace(/[。.]$/,'')}。请点击刷新重试。`;$('subtitle').textContent='当前页面未能加载';$('content').innerHTML='';if(/算法版本已变化|unknown[ _]data[ _]version|未知数据版本|快照.*版本/i.test(String(e.message))){const b=document.createElement('button');b.className='switch-version';b.textContent='切换最新数据';b.onclick=switchLatest;$('status').append(' ',b);syncHealth()}}
function updateVersionNotice(){const b=$('version-notice');if(b)b.hidden=!(state.latestVersion&&state.version&&state.latestVersion!==state.version)}
async function syncHealth(){try{const result=await request('/api/dashboards/health');$('health').textContent='数据服务在线';state.latestVersion=result.data_version||null;updateVersionNotice();return result}catch(e){$('health').textContent='数据服务未连接';return null}}
async function switchLatest(){const health=await syncHealth();if(!health?.data_version){$('status').hidden=false;$('status').textContent='未能获取最新数据版本，请稍后重试。';return}state.version=health.data_version;updateUrl({data_version:state.version},true);updateVersionNotice();loadBoard()}
async function loadBoard(){delete document.querySelector('main').dataset.renderMs;state.renderStart=performance.now();nav();cleanupCharts();$('tabs').innerHTML='';$('controls').innerHTML='';$('warnings').innerHTML='';$('content').innerHTML='';$('status').className='status';$('status').textContent='正在加载看板…';$('status').hidden=false;const {signal,seq}=begin();try{const versionQuery=state.version?`?data_version=${encodeURIComponent(state.version)}`:'';const meta=await request(`/api/dashboards/${encodeURIComponent(state.board)}/metadata${versionQuery}`,signal);if(seq!==state.sequence)return;state.meta=meta;if(!state.version&&meta.data_version){state.version=meta.data_version;updateUrl({data_version:state.version},true)}updateVersionNotice();$('title').textContent=meta.title||BOARDS.find(b=>b[0]===state.board)[1];document.title=`${$('title').textContent} · 七大投研台`;const tabs=meta.tabs||[];if(!tabs.some(t=>t.id===state.panel))state.panel=meta.defaults?.tab||tabs[0]?.id||'';renderTabs();if(!state.panel){$('status').textContent='该看板暂无可用页面';return}await loadPanel(true);}catch(e){showError(e)}}
function renderTabs(){$('tabs').innerHTML=(state.meta?.tabs||[]).map(t=>`<button role="tab" aria-selected="${t.id===state.panel}" class="${t.id===state.panel?'active':''}" data-tab="${esc(t.id)}">${esc(t.label)}</button>`).join('');$('tabs').querySelectorAll('button').forEach(button=>button.onclick=()=>{if(button.dataset.tab===state.panel&&!state.entity)return;state.panel=button.dataset.tab;state.entity=null;state.table={};updateUrl({desk:state.board,tab:state.panel,_detail:null,page:null,sort:null,order:null,desc:null});renderTabs();loadPanel()})}
function query(){const q=params();q.delete('qa');q.delete('desk');if(BOARDS.some(b=>b[0]===q.get('board')))q.delete('board');q.delete('tab');q.delete('_detail');return q}
async function loadPanel(fromBoard=false){delete document.querySelector('main').dataset.renderMs;if(!fromBoard)state.renderStart=performance.now();cleanupCharts();$('content').innerHTML='';$('warnings').innerHTML='';$('status').hidden=false;$('status').className='status';$('status').textContent='正在加载数据…';const {signal,seq}=begin();try{const q=query();let url=state.entity?`/api/dashboards/${encodeURIComponent(state.board)}/entities/${encodeURIComponent(state.entity)}`:`/api/dashboards/${encodeURIComponent(state.board)}/${encodeURIComponent(state.panel)}`;if(q.toString())url+=`?${q}`;const data=await request(url,signal);if(seq!==state.sequence)return;state.data=data;if(data.data_version&&!state.version){state.version=data.data_version;updateUrl({data_version:state.version},true)}render(data);document.querySelector('main').dataset.renderMs=String(Math.round(performance.now()-state.renderStart))}catch(e){showError(e)}}
function renderControls(controls){const q=params();$('controls').innerHTML='';for(const control of controls||[]){if(!control?.key||control.key==='ids'||(state.board==='sentiment'&&control.key.startsWith('w_')))continue;const label=document.createElement('label');label.className='control';const title=document.createElement('span');title.textContent=control.label||control.key;label.append(title);let input;if(control.type==='select'||control.type==='multiselect'||control.multiple){input=document.createElement('select');input.multiple=!!control.multiple||control.type==='multiselect'||control.key==='ids';for(const option of control.options||[]){const o=document.createElement('option');o.value=String(typeof option==='object'?option.value:option);o.textContent=typeof option==='object'?option.label:option;input.append(o)}}else{input=document.createElement('input');input.type=control.type==='number'?'number':control.type==='date'||((control.key==='date'||(state.board==='chips'&&state.panel==='stock'&&control.key==='obs'))&&Array.isArray(state.meta?.calendar_dates))?'date':'text';if(control.placeholder)input.placeholder=control.placeholder}input.dataset.controlKey=control.key;const preset=q.get('preset')??controls.find(c=>c.key==='preset')?.value??'all';const allSignalWindow=state.board==='chips'&&state.panel==='screen'&&control.key==='window'&&preset==='all';input.disabled=!!control.disabled||allSignalWindow;if(allSignalWindow){input.title='全部信号时不可选择触发窗口';label.title=input.title}const raw=q.get(control.key)??control.value??'';if(input.multiple){let selected=Array.isArray(raw)?raw.map(String):String(raw).split(',');if(control.key==='ids'&&!selected.some(v=>[...input.options].some(o=>o.value===v)))selected=Array.isArray(control.value)?control.value.map(String):String(control.value||'').split(',');[...input.options].forEach(o=>o.selected=selected.includes(o.value))}else input.value=raw;let timer,composing=false;const change=e=>{if(composing||e?.isComposing)return;clearTimeout(timer);controlTimers.delete(timer);const apply=()=>{const max=Number(control.max_selections)||(control.key==='ids'?6:Infinity);const selected=input.multiple?[...input.selectedOptions]:[];if(input.multiple&&selected.length>max)selected.slice(max).forEach(o=>o.selected=false);const value=input.multiple?selected.slice(0,max).map(o=>o.value):input.value;updateUrl({[control.key]:value,page:null});state.table={};loadPanel()};if(input.type==='text'||input.type==='number'){timer=setTimeout(()=>{controlTimers.delete(timer);apply()},450);controlTimers.add(timer)}else apply()};input.addEventListener(input.type==='text'||input.type==='number'?'input':'change',change);if(input.type==='text'){input.addEventListener('compositionstart',()=>{composing=true;clearTimeout(timer);controlTimers.delete(timer)});input.addEventListener('compositionend',()=>{composing=false;change()})}const stepKey=state.board==='chips'&&state.panel==='stock'?'obs':'date';if(control.key===stepKey&&Array.isArray(state.meta?.calendar_dates)&&state.meta.calendar_dates.length){const days=[...new Set(state.meta.calendar_dates.filter(d=>typeof d==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(d)))].sort(),current=String(raw||'');const previous=days.filter(d=>d<current).at(-1),next=days.find(d=>d>current&&(stepKey!=='obs'||d<=(q.get('date')||controls.find(c=>c.key==='date')?.value||'9999-12-31')));const make=(text,value,title)=>{const b=document.createElement('button');b.type='button';b.className='date-step';b.textContent=text;b.title=title;b.setAttribute('aria-label',title);b.disabled=!value;b.onclick=e=>{e.preventDefault();if(value){state.table={};updateUrl({[stepKey]:value,page:null});loadPanel()}};return b};label.append(make('‹',previous,'前一交易日'),input,make('›',next,'后一交易日'))}else label.append(input);if(input.multiple&&control.max_selections){const limit=document.createElement('small');limit.className='control-hint';limit.textContent=`最多选 ${control.max_selections} 项`;label.append(limit)}if(allSignalWindow){const hint=document.createElement('small');hint.className='control-hint';hint.textContent='全部信号时不可用';label.append(hint)}$('controls').append(label)}if(state.board==='sentiment')renderWeightControl(controls);if(state.board==='fund_holdings')renderBasket(controls)}
function render(data){$('status').hidden=true;$('status').textContent='';$('subtitle').textContent=data.description||state.meta?.description||'多维数据与历史观察';$('data-date').textContent=data.data_date?`数据日期 ${data.data_date}`:'';$('data-version').textContent=data.data_version?`版本 ${data.data_version}`:'';const controls=[...(data.controls?.length?data.controls:state.meta?.controls||[])];if(!controls.some(c=>c.key==='date')&&(state.meta?.defaults?.date||data.data_date))controls.unshift({key:'date',label:'观察日期',type:'date',value:state.meta?.defaults?.date||data.data_date||''});renderControls(controls);const notes=data.warnings||[];$('warnings').innerHTML=notes.length?`<details class="data-notes"><summary>数据说明 <span>${notes.length}</span></summary>${notes.map(w=>`<div>${esc(typeof w==='string'?w:w.message||JSON.stringify(w))}</div>`).join('')}</details>`:'';const content=$('content');content.className='content '+(state.board==='national_team'&&state.panel==='stock'?'national-stock':'');content.innerHTML='';if(state.entity){const head=document.createElement('div');head.className='entity-head full';head.style.gridColumn='1 / -1';head.innerHTML=`<button class="back">← 返回 ${esc((state.meta?.tabs||[]).find(t=>t.id===state.panel)?.label||'看板')}</button><h2>${esc(data.title||state.entity)}</h2>`;head.querySelector('button').onclick=()=>{state.entity=null;updateUrl({_detail:null});loadPanel()};content.append(head)}const sections=prepareSections(data.sections||[]);if(!sections.length){$('status').hidden=false;$('status').textContent=data.missing_reason||'当前条件下暂无数据';return}let slot=0;for(const section of sections){const layout=sectionLayout(state.board,state.panel,section);renderSection(section,content,layout);if(section.kind!=='kpi')slot++}}
function quality(section){const q=section.quality;if(!q)return '';const s=typeof q==='string'?q:JSON.stringify(q);return /估算|estimat|approximat|proxy|近似/i.test(s)?`<span class="badge" title="${esc(s)}">估算</span>`:''}
const META_FIELDS=new Set(['source','provider','data_version','fetched_at','day_id','quality_status','pit_status','origin','as_of','source_version','created_at','updated_at','file_path']);
const FRIENDLY={south_sh:'沪市港股通',south_sz:'深市港股通',north_sh:'沪股通',north_sz:'深股通',rank:'排名',temperature_proxy:'托底温度',trade_type:'交易方向',change_vol:'变动股数',avg_price:'成交均价',disclosed_amount:'披露金额',exchange:'交易所',category:'分类',event_count:'事件数',flow_5_observations:'5日净额',flow_20_observations:'20日净额',margin_repay:'融资偿还',short_balance:'融券余额',short_sell_volume:'融券卖出量',short_repay_volume:'融券偿还量',total_balance:'融资融券余额',prev_date:'上期日期',financing_buy_turnover_ratio:'融资买入占成交',cumulative_net_buy:'累计净买入',etf_count:'ETF只数',valid_flow_count:'有效只数',line:'项目',direction:'方向',window_days:'窗口天数',valid_days:'有效天数',source_as_of:'来源截止日',observed_amount:'观察金额',estimated_amount:'估算金额',financing_net_buy:'融资净买入',market_net:'市场净额',etf_net_subscription:'ETF净申购',southbound_net_buy:'南向净买入'};
const VALUE_LABELS={BSE:'北交所',SZSE:'深交所',SSE:'上交所',south_total:'南向合计',south_sz:'深市港股通',south_sh:'沪市港股通',north_sh:'沪股通',north_sz:'深股通',strategy_style:'策略风格',cross_border:'跨境',industry_theme:'行业主题',other:'其他',broad:'宽基',unclassified:'未分类'};
const friendly=c=>FRIENDLY[c.key]||c.label||c.key;
function directional(key='',label=''){return /(^|_)(net|return|excess|change|delta|flow_[0-9])|涨跌|收益|净流|净买|净申购|净额|变动|变化|超额/.test(key+' '+label)&&!/日期|来源|覆盖|数量|只数|排名|分位|股息|分红/.test(label)}
function directionClass(value,key,label){return typeof value==='number'&&directional(key,label)?value>0?'positive':value<0?'negative':'':''}
function compact(n){const a=Math.abs(n);if(a>=1e8)return (n/1e8).toLocaleString('zh-CN',{maximumFractionDigits:2})+' 亿';if(a>=1e4)return (n/1e4).toLocaleString('zh-CN',{maximumFractionDigits:2})+' 万';return n.toLocaleString('zh-CN',{maximumFractionDigits:2})}
function monetary(key='',label='',format=''){return format==='money'||format!=='percent'&&!/ratio|percent|pct|rate|yield|count|days|volume|shares|权重|比例|收益率|换手|只数|股数|份额/.test(key+' '+label)&&/amount|market_value|margin_balance|margin_buy|margin_repay|short_balance|net_flow|main_net|net_buy|subscription|turnover|fund_size|estimated_value|raised|cumulative_flow|flow_[0-9]|金额|市值|净额|净买|净申购|成交额|融资余额|规模/.test(key+' '+label)}
function display(value,format,key='',label=''){if(value===null||value===undefined||value==='')return '—';if(typeof value==='number'){if(format==='percent'||format==='%')return `${(value*100).toFixed(2)}%`;if(monetary(key,label,format))return compact(value);return Number.isInteger(value)?value.toLocaleString('zh-CN'):value.toLocaleString('zh-CN',{maximumFractionDigits:2})}if(typeof value==='boolean')return value?'是':'否';if(typeof value==='object')return JSON.stringify(value);if(key==='entity_id'){const entities={hj_inv:'汇金投资',hj_am:'汇金资管',zj:'证金',sb_council:'社保理事会',sb_pf:'社保组合',gx:'国新',ct:'诚通'};return entities[value]||String(value)}if(key==='trade_type'){const trades={IN:'增持',DE:'减持'};return trades[value]||String(value)}return ['exchange','category','channel'].includes(key)?(VALUE_LABELS[value]||String(value)):String(value)}
function metadataDetails(s){const values=[];for(const key of META_FIELDS){const vs=[...new Set((s.rows||[]).map(r=>r[key]).filter(v=>v!=null&&v!==''))];if(vs.length)values.push(`${friendly({key,label:key})}：${vs.slice(0,3).join('、')}${vs.length>3?'…':''}`)}for(const [key,label] of [['formula_id','公式'],['formula_version','公式版本'],['sample_scope','样本范围'],['coverage','覆盖情况'],['missing_reason','缺失原因']])if(s[key]!=null)values.push(`${label}：${key==='coverage'&&Array.isArray(s[key])?s[key].map(r=>`${r.dimension||r.dimension_id} ${r.valid_items??'—'}/${r.expected_items??'—'}${r.missing_reason?'（'+r.missing_reason+'）':''}`).join('；'):typeof s[key]==='object'?JSON.stringify(s[key]):s[key]}`);return values.length?`<details class="meta-details"><summary>口径、覆盖与来源</summary>${values.map(v=>`<div>${esc(v)}</div>`).join('')}</details>`:''}
function addDataExport(section,body,head){
 const button=document.createElement('button');button.className='chart-export';button.textContent='↓ 出图';button.title='将当前可见内容保存为 PNG';
 button.onclick=async()=>{
  await document.fonts.ready;const table=body.querySelector('table');let rows=[];
  if(table){const header=[...table.querySelectorAll('thead th')].map(e=>e.innerText.replace(/\s*[↕↑↓]\s*$/,'').trim());rows.push({header:true,cells:header});for(const tr of table.querySelectorAll('tbody tr'))rows.push({group:tr.classList.contains('group-row'),cells:[...tr.querySelectorAll('td')].map(e=>(e.dataset.export||e.innerText).trim())})}
  else {const items=[...body.querySelectorAll('.kpi')].filter(e=>e.getClientRects().length);for(let i=0;i<items.length;i+=4){let slice=items.slice(i,i+4);rows.push({header:true,cells:slice.map(e=>e.querySelector('.kpi-name')?.innerText||'')});rows.push({cells:slice.map(e=>e.querySelector('.kpi-value')?.innerText||'')})}}
  if(!rows.length)rows=[{cells:[body.querySelector('.empty')?.innerText||'暂无可展示数据']}];const ctx=document.createElement('canvas').getContext('2d');ctx.font='12px -apple-system, BlinkMacSystemFont, sans-serif';const n=Math.max(...rows.map(r=>r.cells.length));const widths=Array.from({length:n},(_,i)=>Math.min(500,Math.max(88,...rows.map(r=>ctx.measureText(r.cells[i]||'').width+24))));ctx.font='600 15px -apple-system, BlinkMacSystemFont, sans-serif';const width=Math.max(500,Math.ceil(ctx.measureText(section.title||'数据面板').width+28),Math.ceil(widths.reduce((a,b)=>a+b,0)+28)),height=72+rows.length*32+18,scale=2;ctx.canvas.width=width*scale;ctx.canvas.height=height*scale;ctx.scale(scale,scale);ctx.fillStyle='#fff';ctx.fillRect(0,0,width,height);ctx.fillStyle='#252525';ctx.font='600 15px -apple-system, BlinkMacSystemFont, sans-serif';ctx.fillText(section.title||'数据面板',14,25);ctx.fillStyle='#606269';ctx.font='11px -apple-system, BlinkMacSystemFont, sans-serif';ctx.fillText([state.data?.data_date||state.data?.freeze_date,state.version].filter(Boolean).join('  ·  '),14,47);let y=72;
  for(const row of rows){if(row.header||row.group){ctx.fillStyle=row.header?'#f5f5f6':'#f5f5f6';ctx.fillRect(14,y-21,width-28,30)}let x=14;for(let i=0;i<n;i++){let text=row.cells[i]||'';ctx.fillStyle=row.header?'#606269':'#252525';ctx.font=(row.header?'500 ':'')+'12px -apple-system, BlinkMacSystemFont, sans-serif';const max=widths[i]-16;while(text.length>1&&ctx.measureText(text).width>max)text=text.slice(0,-1);if(text!==(row.cells[i]||''))text=text.slice(0,-1)+'…';ctx.fillText(text,x+8,y-1);x+=widths[i]}ctx.strokeStyle='#e3e5ea';ctx.beginPath();ctx.moveTo(14,y+9);ctx.lineTo(width-14,y+9);ctx.stroke();y+=32}
  const a=document.createElement('a');a.download=`${section.title||'数据面板'}.png`;a.href=ctx.canvas.toDataURL('image/png');a.click()
 };head.append(button)
}
function renderSection(s,parent,layout){const el=document.createElement('section');const kind=s.kind||'table';el.className=`panel ${kind==='kpi'?'kpi-panel':''}`;el.dataset.sectionId=s.id||'';if(s.layout_group)el.dataset.layoutGroup=String(s.layout_group);el.style.setProperty('--span',layout.span);el.style.setProperty('--chart-height',`${layout.height}px`);el.innerHTML=`<div class="panel-head"><div><div class="panel-title">${esc(s.title||'数据面板')}${quality(s)}</div>${s.description?`<div class="panel-sub">${esc(s.description)}</div>`:''}</div><div class="panel-tools"></div></div><div class="panel-body"></div>`;parent.append(el);const tools=el.querySelector('.panel-tools');for(const action of s.actions||[]){const button=document.createElement('button');button.className='panel-action';button.textContent=action.label||'查看';button.onclick=()=>performAction(action,{});tools.append(button)}const body=el.querySelector('.panel-body');const rows=Array.isArray(s.rows)?s.rows:[];if(!rows.length){body.innerHTML=`<div class="empty"><strong>暂无可展示数据</strong><span>${esc(s.missing_reason||s.missing_detail||'当前条件下没有结果')}</span></div>`;if(kind==='kpi'||kind==='table')addDataExport(s,body,tools);return}if(state.board==='sentiment'&&state.panel==='dimensions'&&s.id==='dimension-cards'){renderDimensionCards(s,body)}else if(state.board==='valuation'&&state.panel==='overview'&&s.id==='matrix'){renderValuationMatrix(s,body);addDataExport(s,body,tools)}else if(kind==='kpi'){renderKpi(s,body);addDataExport(s,body,tools)}else if(kind==='table'){renderTable(s,body);addDataExport(s,body,tools)}else if(['line','bar','heatmap','scatter','bubble','timeline','candlestick','gauge','radar'].includes(kind)){renderChart(s,body,tools);body.insertAdjacentHTML('beforeend',metadataDetails(s))}else{renderTable(s,body);addDataExport(s,body,tools)}}
